ALTER TABLE public.service_packages ADD COLUMN IF NOT EXISTS delivery_duration INT DEFAULT 3, ADD COLUMN IF NOT EXISTS delivery_unit TEXT DEFAULT 'days', ADD COLUMN IF NOT EXISTS features JSONB DEFAULT '[]'::jsonb; ALTER TABLE public.service_packages DROP CONSTRAINT IF EXISTS service_packages_delivery_days_check; ALTER TABLE public.service_packages ADD CONSTRAINT service_packages_delivery_days_check CHECK (delivery_days >= 0); UPDATE public.service_packages SET delivery_duration = COALESCE(delivery_days, 3), delivery_unit = 'days' WHERE delivery_duration IS NULL OR delivery_unit IS NULL;
